criteria.query:
let online = Heartbeat | where TimeGenerated > ago(30m) | extend Host = toupper(tostring(split(Computer, '.')[0])) | distinct Host;
let scanned = Event | where TimeGenerated > ago(3h) and EventLog == 'REF' and Source == 'REF-Consistency' and EventID == 3000 | extend Host = toupper(tostring(split(Computer, '.')[0])) | distinct Host;
online | join kind=leftanti scanned on Host
